<?php use App\Core\CSRF; $slug=$routeSlug; ?>
<section class="container py-5" style="max-width:960px"><div class="text-center mb-5"><span class="badge text-bg-primary mb-2">ApPlanner Auto</span><h1 class="display-5 fw-bold"><?=htmlspecialchars($tenant['name'])?></h1><p class="lead text-secondary">Agende pelo serviço e pelo box disponível. Seu veículo fica com histórico completo do atendimento.</p></div>
<div class="card shadow-sm"><div class="card-body p-4"><form method="post" action="/auto/<?=rawurlencode($slug)?>/book" id="auto-book" class="row g-3"><?=CSRF::field()?><div class="col-md-6"><label class="form-label">Serviço</label><select name="service_id" id="auto-service" class="form-select" required><option value="">Escolha</option><?php foreach($services as $s):?><option value="<?=(int)$s['id']?>" data-price="<?=$s['price']?>" data-duration="<?=$s['duration_minutes']?>"><?=htmlspecialchars($s['name'])?> · R$ <?=number_format((float)$s['price'],2,',','.')?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Data</label><input type="date" id="auto-date" class="form-control" min="<?=date('Y-m-d')?>" required></div><div class="col-12"><label class="form-label">Horários realmente disponíveis</label><div id="auto-slots" class="d-flex flex-wrap gap-2"><span class="text-secondary">Escolha serviço e data.</span></div><input type="hidden" name="bay_id" id="auto-bay"><input type="hidden" name="starts_at" id="auto-start"></div><hr class="my-3"><div class="col-12"><h2 class="h5">Seus dados</h2></div><div class="col-md-4"><label class="form-label">Nome</label><input name="name" class="form-control" required></div><div class="col-md-4"><label class="form-label">WhatsApp</label><input name="phone" class="form-control" inputmode="tel" required></div><div class="col-md-4"><label class="form-label">E-mail</label><input name="email" type="email" class="form-control"></div><div class="col-12"><h2 class="h5 mt-2">Veículo</h2></div><div class="col-md-3"><label class="form-label">Placa</label><input name="plate" maxlength="8" class="form-control" placeholder="ABC1D23"></div><div class="col-md-3"><label class="form-label">Marca</label><input name="make" class="form-control" placeholder="Toyota"></div><div class="col-md-3"><label class="form-label">Modelo</label><input name="model" class="form-control" required placeholder="Corolla"></div><div class="col-md-3"><label class="form-label">Ano</label><input type="number" name="year" min="1900" max="<?=date('Y')+1?>" class="form-control"></div><div class="col-md-4"><label class="form-label">Cor</label><input name="color" class="form-control"></div><div class="col-md-8"><label class="form-label">Observações</label><input name="notes" class="form-control" placeholder="Ex.: atenção à roda dianteira direita"></div><div class="col-12 d-grid mt-4"><button class="btn btn-primary btn-lg" id="auto-submit" disabled>Confirmar reserva</button></div></form></div></div></section>
<script>(()=>{const svc=document.querySelector('#auto-service'),date=document.querySelector('#auto-date'),box=document.querySelector('#auto-slots'),bay=document.querySelector('#auto-bay'),start=document.querySelector('#auto-start'),submit=document.querySelector('#auto-submit');async function load(){bay.value='';start.value='';submit.disabled=true;if(!svc.value||!date.value){box.innerHTML='<span class="text-secondary">Escolha serviço e data.</span>';return}box.innerHTML='<span class="text-secondary">Buscando horários...</span>';try{const r=await fetch('/auto/<?=rawurlencode($slug)?>/availability?service_id='+encodeURIComponent(svc.value)+'&date='+encodeURIComponent(date.value),{headers:{'Accept':'application/json'}});const d=await r.json();box.innerHTML='';if(!d.slots?.length){box.innerHTML='<div class="alert alert-warning w-100 mb-0">Nenhum box disponível nessa data.</div>';return}d.slots.forEach(s=>{const b=document.createElement('button');b.type='button';b.className='btn btn-outline-primary';b.textContent=s.time+' · '+s.bay_name;b.onclick=()=>{[...box.querySelectorAll('button')].forEach(x=>x.classList.replace('btn-primary','btn-outline-primary'));b.classList.remove('btn-outline-primary');b.classList.add('btn-primary');bay.value=s.bay_id;start.value=s.starts_at;submit.disabled=false};box.appendChild(b)})}catch(e){box.innerHTML='<div class="alert alert-danger w-100 mb-0">Não foi possível consultar os horários.</div>'}}svc.addEventListener('change',load);date.addEventListener('change',load)})();</script>
